import re
from collections import OrderedDict


def prepare(d):
    for key, value in list(d.items()):
        d[key] = value[0]
    return d


def differs(set1, set2):
    return is_empty(set(set1.items()).difference(set(set2.items())))


def is_empty(some_set):
    return len(some_set)


class ChangeSWConfigParams(object):
    def __init__(self, path):
        self.path = path

    def change_params(self, *args):
        """
        Method change params in swconfig.txt file
        """
        lines = self._read_swconfig()
        swconfig_hex_params, swconfig_dec_params = self._parse_swconfig(lines)
        new_hex_params, new_dec_params = self._parse_swconfig(list(args))
        swconfig_hex_params.update(new_hex_params)
        swconfig_dec_params.update(new_dec_params)
        to_write = self._prepare_content(swconfig_hex_params, swconfig_dec_params)
        self._write_swconfig(to_write)

    def check_if_flags_are_set(self, *args):
        lines = self._read_swconfig()
        swconfig_hex_params, swconfig_dec_params = self._parse_swconfig(lines)
        new_hex_params, new_dec_params = self._parse_swconfig(list(args))

        return not differs(prepare(new_hex_params), prepare(swconfig_hex_params)) and not differs(
            prepare(new_dec_params), prepare(swconfig_dec_params)
        )

    def _parse_swconfig(self, lines):
        parsed_hex_params = OrderedDict()
        parsed_dec_params = OrderedDict()

        multiline_comment_regexp = r"\s*/\*.*?\*/\s*"
        swconfig_text = '\n'.join(lines)
        swconfig_text_wo_comments = re.sub(multiline_comment_regexp, "\n", swconfig_text, flags=re.DOTALL)
        lines = swconfig_text_wo_comments.split('\n')

        for line in lines:
            line = line.strip()
            if not (line.startswith("#") or line == "\n" or line == "" or "=" not in line):
                line = line.split('=')
                line[0] = line[0].replace(" ", "")
                if not line[0].isdigit():
                    parsed_hex_params[int(line[0], 16)] = line[1].split()
                else:
                    parsed_dec_params[int(line[0])] = line[1].split()
        return parsed_hex_params, parsed_dec_params

    def _read_swconfig(self):
        with open(self.path, 'r') as f:
            return f.readlines()

    def _prepare_content(self, hex_params, dec_params):
        to_write = "\n".join(["{} = {}".format('0x' + str(hex(k))[2:].upper(), " ".join(v)) for k, v in list(hex_params.items())])
        to_write += "\n"
        to_write += "\n".join(["{} = {}".format(str(k), " ".join(v)) for k, v in list(dec_params.items())])
        to_write += "\n"
        return to_write

    def _write_swconfig(self, buff):
        with open(self.path, 'w') as f:
            f.write(buff)
